//! Smooth chroma compression on a constant-luminance RGB ray, not perceptual gamut mapping.
use crate::effects::{p,Params,Frame};
pub fn compress(c:[f64;3],weights:[f64;3],ceiling:f64,knee:f64)->[f64;3]{let y=(0..3).map(|j|weights[j]*c[j]).sum::<f64>();if y<=0.||y>=ceiling{return [y.clamp(0.,ceiling);3]}let mut edge:f64=f64::INFINITY;for v in c{let d=v-y;if d>0.{edge=edge.min((ceiling-y)/d)}else if d<0.{edge=edge.min(-y/d)}}let distance=1./edge.max(1e-30);if distance<=knee{return c}let mapped=knee+(1.-knee)*(1.-(-(distance-knee)/(1.-knee)).exp());let scale=mapped/distance;c.map(|v|y+(v-y)*scale)}
pub fn apply(pr:&Params,f:&mut Frame,t:f64)->Result<(),String>{super::frame::validate(f)?;let g=p(pr,"gamut",0.,t) as f64;let ceiling=p(pr,"ceiling",1.,t) as f64;let knee=p(pr,"knee",0.8,t) as f64;if g.fract()!=0.||!(0. ..=7.).contains(&g)||!ceiling.is_finite()||!(1e-6 ..=1000.).contains(&ceiling)||!(0. ..=0.99).contains(&knee){return Err("invalid gamutray params".into())}let weights=super::managed::luma_weights(g as usize);for(i,p) in f.d.chunks_exact_mut(4).enumerate(){if i%65536==0{crate::guard::check()}let c=[p[0] as f64,p[1] as f64,p[2] as f64];if c.iter().any(|v|!v.is_finite()){return Err("nonfinite gamutray input".into())}let c=compress(c,weights,ceiling,knee);for j in 0..3{p[j]=c[j] as f32}}Ok(())}
pub fn catalog()->Vec<super::Entry>{vec![("soft_gamut_ray","Smooth constant-luminance RGB chroma ray compression to0..ceiling with a chroma-boundary knee. Explicitlineargamut. Y outside0..ceiling becomes boundedneutral, so tonemapfirst. RGB-ray hue direction retained, NOT perceptualhue or ACESgamutcompression. Alphaunchanged.",&[("gamut",0.,"linear gamut0..7"),("ceiling",1.,"positive RGBceiling up to1000"),("knee",0.8,"boundarydistance knee0..0.99")])]}
